    # This should work if get_typed_signature handles __wrapped__
    @wrapper
    def my_endpoint(item: "Model"):
        return {"item": item}

    sig = get_typed_signature(my_endpoint)
    # Check if the annotation for 'item' is resolved to Model
    param = sig.parameters["item"]
    assert param.annotation is Model

