def test_wrapped_forward_ref():
    # Create a separate module-like environment by using a function
    def outer():
        class LocalModel:
            pass

        def inner(a: "LocalModel"):
            return a

        @functools.wraps(inner)
        def wrapped(*args, **kwargs):
            return inner(*args, **kwargs)

        # This should fail if get_typed_signature uses wrapped.__globals__ 
        # instead of inner.__globals__ (though in this case they are the same)
        # But if wrapped was defined elsewhere...

        return wrapped, LocalModel

    wrapped_func, LocalModel = outer()
    try:
        sig = get_typed_signature(wrapped_func)
        print(f"Annotation: {sig.parameters['a'].annotation}")
        assert sig.parameters['a'].annotation is LocalModel
        print("Test passed!")
